"""Render Vietnamese audit findings with verified source anchors and sanitized evidence."""
import csv,json,re
from pathlib import Path
ROOT=Path(__file__).resolve().parents[3]
OUT=Path(__file__).resolve().parent
E=OUT/'evidence'
def read(name):return json.loads((E/name).read_text(encoding='utf-8-sig'))
def link(path,needle=None,label=None):
 p=ROOT/path if not path.startswith('evidence/') else OUT/path
 assert p.exists(),path
 suffix=''
 if needle:
  lines=p.read_text(encoding='utf-8',errors='replace').splitlines()
  matches=[i+1 for i,l in enumerate(lines) if needle in l]
  assert matches,(path,needle)
  suffix=':'+str(matches[0])
 return f'[{label or path}](<{p.as_posix()}{suffix}>)'

